from pathlib import Path
p=Path('Scripts/crafting_ui.gd')
s=p.read_text(encoding='utf-8')
s=s.replace('Vector2(470, 240)', 'Vector2(470, 264)').replace('168 + recipe.cost.size() * 34','192 + recipe.cost.size() * 34')
s=s.replace('top_bar.name = "TopBar"','top_bar.name = "TopBar"\n\ttop_bar.visible = false')
s=s.replace('title.set_meta("pixelmania_font_size", 28)','title.set_meta("pixelmania_font_size", 40)\n\ttitle.set_meta("pixelmania_text_shadow", false)')
s=s.replace('PixelUIStyle.apply_label_shadow(title, 28)','PixelUIStyle.apply_label_shadow(title, 40, Color("321b3d"))\n\ttitle.add_theme_color_override("font_shadow_color", Color.TRANSPARENT)\n\ttitle.add_theme_constant_override("shadow_offset_x", 0)\n\ttitle.add_theme_constant_override("shadow_offset_y", 0)')
s=s.replace('PixelUIStyle.apply_small_label(title_sub, 14)','title_sub.set_meta("pixelmania_text_shadow", false)\n\tPixelUIStyle.apply_label_shadow(title_sub, 16, Color("321b3d"))\n\ttitle_sub.add_theme_color_override("font_shadow_color", Color.TRANSPARENT)')
s=s.replace('recipe_area.add_theme_stylebox_override("panel", station_section_style())','recipe_area.add_theme_stylebox_override("panel", StyleBoxEmpty.new())')
s=s.replace('card.name = "RecipeCard_" + str(output.item_id)','card.name = "RecipeCard_" + str(output.item_id)\n\tcard.set_meta("pixelmania_panel_shadow", false)')
s=s.replace('icon_frame.size = Vector2(64, 64)','icon_frame.size = Vector2(88, 88)')
s=s.replace('icon.size = Vector2(48, 48)','icon.size = Vector2(72, 72)')
s=s.replace('Vector2(90, 14), Vector2(274, 42), 22','Vector2(118, 14), Vector2(330, 54), 28')
s=s.replace('Vector2(90, 58), Vector2(350, 24), 15','Vector2(118, 72), Vector2(330, 24), 15')
s=s.replace('"x%d" % int(output.amount), Vector2(376, 20), Vector2(76, 30), 22','str(int(output.amount)), Vector2(20, 72), Vector2(74, 24), 20')
s=s.replace('output_count.modulate = Color("ffe577")','output_count.modulate = Color.WHITE')
s=s.replace('Vector2(20, 88), Vector2(260, 22)','Vector2(20, 112), Vector2(260, 22)').replace('Vector2(322, 88), Vector2(128, 22)','Vector2(322, 112), Vector2(128, 22)')
s=s.replace('var row_y := 112.0 + i * 34.0','var row_y := 136.0 + i * 34.0')
s=s.replace('"CRAFT x%d" % int(output.amount)', '"CRAFT %d" % int(output.amount)')
p.write_text(s,encoding='utf-8')
